/* Explicit consequences remain in the save: no stat threshold silently substitutes a decision. */
const summerConsequences=[
[[['Ты берёшь трубку. Неудобно настаивать, когда собеседница так расстроена, но ещё неудобнее начинать отпуск с отказа от собственных желаний.'],['Я понимаю, что город занят. Всё-таки позвоните, пожалуйста, ещё кому-нибудь.','summer-heroine'],['Бьянки перезванивает через четверть часа: свободна только комната без окна над баром. Ты благодаришь за попытку и отказываешься. Теперь остаться здесь — твоё решение.'],['Если передумаешь завтра, я помогу с чемоданом. Без обид.','summer-sasha']], [['Кофе оказывается крепким и чуть горьким. Саша подвигает сахарницу, но не ставит чашку тебе в руки: оставляет выбрать самой.'],['Давай сначала посмотрим комнаты. Кофе ещё не означает, что я согласилась.','summer-heroine'],['Договорились. Никаких обязательств мелким шрифтом.','summer-sasha']]],
[[['Ты проверяешь замок дважды. Ключ туго поворачивается, зато щелчок получается уверенным.'],['Мне важно иногда закрыть дверь и ни на что не отвечать.','summer-heroine'],['Тогда я буду оставлять записки. На них тоже можно не отвечать.','summer-sasha']], [['Утро тебе, вечер мне? Или это уже государственная граница?','summer-sasha'],['Лучше два стула. И право молчать на обоих.','summer-heroine'],['Вы переносите второй стул к перилам. Его ножка царапает плитку; впервые в этой квартире появляется звук вещи, которую вы сделали вместе.']]],
[[['О моей работе пока не надо. Но про твою мне, возможно, интересно.','summer-heroine'],['Возможно — уже неплохое начало. Только учти: я могу полчаса говорить об одном пятне света.','summer-sasha']], [['Спасибо, что не спрашиваешь. Обычно после этой фразы начинают спрашивать осторожнее.','summer-heroine'],['Я могу просто помыть чашки. Это у меня лучше получается, чем осторожность.','summer-sasha'],['Он встаёт к раковине. Ты остаёшься рядом и вытираешь тарелки: разговор закончился, а неловкости почему-то нет.']]],
[[['Плёнка заканчивается. Мне полезно помнить, что не всё можно переснять.','summer-sasha'],['А если самое важное случится на тридцать седьмом кадре?','summer-heroine'],['Тогда придётся запомнить. Я иногда забываю, что это тоже разрешено.','summer-sasha']], [['Ты раскладываешь отпечатки в другом порядке: сначала пустые стулья, потом руки старухи, потом её смех.'],['Так она не просто смешная. У неё будто был целый день до этой минуты.','summer-heroine'],['Саша долго смотрит на стол, затем записывает твой порядок на обороте конверта.'],['Оставим так. Ты увидела то, что я пропустил.','summer-sasha']]],
[[['Только сначала мне. И никуда не выкладывать.','summer-heroine'],['Сначала тебе. Сейчас возьму цифровую — плёнку сегодня не успеем проявить.','summer-sasha'],['Ты ждёшь команды улыбнуться. Вместо неё Саша спрашивает, что продавец сказал про помидоры, и щёлкает затвором, когда ты начинаешь смеяться.'],['На снимке ты не стараешься казаться удобной. Волосы растрепал ветер, глаза чуть прищурены; ты узнаёшь себя и неожиданно не хочешь ничего исправлять.'],['Мне нравится. Правда нравится. Можно мне его оставить?','summer-heroine'],['Он отправляет файл тебе. Впервые за долгое время слово «красивая» возникает раньше привычного списка недостатков.']], [['Сегодня не хочу. Давай лучше найдём что-нибудь, что понравится нам обоим.','summer-heroine'],['Саша сразу опускает камеру. Вы выбираете прилавок с лимонами; ты замечаешь руку продавщицы, поправляющую бумажный пакет, и просишь подождать.'],['Вот теперь.','summer-heroine'],['Он делает кадр в тот миг, когда она кладёт лишний лимон сверху. Этот маленький сговор остаётся вашим первым совместным снимком.']]],
[[['Ты открываешь документ и убираешь из первой строки одно лишнее слово. Потом возвращаешь его. Такая крошечная работа — и всё же это уже не закрытая папка.'],['На отдельном листе ты записываешь дату первой версии. Пока не знаешь зачем; просто хочешь, чтобы у этих страниц снова появилось время.']], [['Ты прижимаешь страницы стаканом, чтобы их не унесло сквозняком. Сегодня не нужно превращать возвращение к себе в ещё одно задание.'],['Из коридора доносится стук. Ты накрываешь рукопись чистым листом и идёшь открывать: оставить её на виду пока можешь только для себя.']]],
[[['Я редактирую книги. Иногда люди благодарят редактора в конце. Иногда забывают, что он вообще был.','summer-heroine'],['А ты хочешь быть в конце?','summer-sasha'],['Я хочу однажды быть на обложке. С собственной книгой.','summer-heroine'],['Саша не просит прислать рукопись и не обещает знакомства в издательстве. Он только убирает со стола телефон, словно твоя фраза заслуживает всего его внимания.']], [['Момент, когда человек перестаёт следить за лицом. Не потому, что я его перехитрил. Потому, что больше не ждёт подвоха.','summer-sasha'],['Ты долго молчишь, проводя пальцем по неровному краю стакана. Свою историю сегодня рассказывать не хочется — и впервые это не кажется провалом близости.']]],
[[['Ты снимаешь афишу целиком, затем отдельно мелкий шрифт и время показа. Руки дрожат; первый кадр приходится удалить и сделать заново.'],['Саша заслоняет тебя от потока прохожих. У вас появляется точный адрес и время, а у страха — первая вещь, которую можно сделать.']], [['Отведи меня отсюда. Только не спрашивай пока.','summer-heroine'],['У воды он покупает бутылку и откручивает тугую крышку. Ты считаешь белые лодки, пока сердце перестаёт биться где-то в горле.'],['Когда захочешь, вернёмся к афише. Она никуда не денется.','summer-sasha']]],
[[['Ты создаёшь папку с копиями. Даты, письма, вложения: маленькие твёрдые предметы на месте огромного бесформенного «мне не поверят».'],['Саша спрашивает, куда положить зарядку, и отходит. За клавиатурой остаёшься ты.']], [['Побудь здесь. Я сейчас не могу ещё и рассказывать всё правильно.','summer-heroine'],['Не нужно правильно. И рассказывать не нужно.','summer-sasha'],['Он приносит хлеб и воду. Через некоторое время ты сама открываешь архив: тишина рядом с ним оказывается поддержкой, а не ожиданием отчёта.']]],
[[['Ты видел моё имя в документах раньше?','summer-heroine'],['В списке гостей — нет. Фамилию Кирилла в заказе видел. Я должен был сказать об этом, как только ты показала афишу.','summer-sasha'],['Ответ неприятен именно тем, что в нём нет удобного оправдания. Ты кладёшь пропуск на стол и просишь больше ничего не скрывать из желания тебя поберечь.']], [['Мне нужно побыть одной. Не решай за меня, что я должна сейчас понять.','summer-heroine'],['Он оставляет пропуск на столе и выходит на улицу. Впервые за день ты слышишь квартиру без чужих шагов. Злость ещё здесь, но теперь ей есть место.']]],
[[['Не проси меня поверить тебе только потому, что ты хорошо со мной обращаешься.','summer-heroine'],['Не буду. Я могу рассказать, что знаю о показе. А дальше ты решишь сама.','summer-sasha'],['Он присылает рабочее расписание и имя координатора. Ты сохраняешь сообщение, но не отвечаешь сердечком из вежливости.']], [['Встреть меня у выхода. Не знаю, какой я оттуда выйду.','summer-heroine'],['У боковой лестницы. Даже если захочешь молчать всю дорогу.','summer-sasha'],['Вы уточняете место — фонарь возле закрытого киоска. Тебе становится легче от этой почти смешной конкретности.']]],
[[['Сегодня никаких случайных кадров. Даже если будет красивый свет.','summer-heroine'],['Я услышал.','summer-sasha'],['Он убирает камеру в сумку ещё на лестнице. Это занимает секунду; тебе важна именно эта секунда, в которой просьба превращается в действие.']], [['После показа пойдём пешком? Не хочу снова возвращаться одна в гостиничную тишину.','summer-heroine'],['Пойдём. По длинной дороге, если короткая не подойдёт.','summer-sasha'],['Ты ловишь себя на слове «домой». Пока оно означает только чужую квартиру, два стула и чашку, которую уже узнаёшь на полке.']]],
[[['Ты просишь продюсера прислать копию документа и проверяешь, что снимок подписи получился резким.'],['Это не моя подпись. Я хочу обсудить документ после показа — с вами, а не в коридоре с Кириллом.','summer-heroine'],['Женщина перестаёт листать папку и записывает твой адрес. В телефоне остаётся не только угроза чужого разговора, но и назначенная встреча.']], [['Ты печатаешь ответ без восклицательного знака. «Теперь разговор будет на моих условиях. Здесь, при продюсере. После фильма».'],['На экране появляется «печатает», исчезает и возникает снова. Ты переворачиваешь телефон. В этот раз ждать придётся ему.']]]
];
function summerBranchFrames(run){return summerConsequences[run.step][run.decisions[run.step]].flatMap(([text,speaker])=>compactFrame({text,...(speaker?{speaker}: {})}));}
function chooseSummer(index){const r=state.runs[1];if(r.pendingChoice)return;const choice=stories[1].scenes[r.step][2][index];if(!choice)return;r.decisions??={};r.decisions[r.step]=index;r[choice[1]]++;r.pendingChoice=true;r.beat=0;save();showScene();}
// Later callbacks are composed per save without mutating the shared script.
function summerSceneFrames(run){const base=readingFrames[1][run.step],d=run.decisions||{};let extra=[];
 if(run.step===3)extra=[['На кухонном столе между персиками лежит тяжёлая камера. Ты передвигаешь хлебницу, стараясь не задеть ремень.'],['Она работает или это для красоты?','summer-heroine'],['Работает. Для красоты здесь, кажется, только я. И то до первого заказа.','summer-sasha'],['Ты улыбаешься. Он снимает крышку с объектива и подносит камеру к окну, но не направляет на тебя.'],['Ты фотограф?','summer-heroine'],['Да. На фестивале снимаю для агентства. А по утрам хожу по городу без задания — чтобы не забывать, зачем вообще начал.','summer-sasha'],['Он показывает потёртое место на ремне. Его зашивали разными нитками: чёрной, серой и однажды, видимо от отчаяния, красной.'],['Первую камеру купил с рук. Потом три месяца снимал один двор. Думал, надо уехать куда-нибудь далеко, чтобы началось интересное.','summer-sasha'],['А оказалось?','summer-heroine'],['Надо было познакомиться с людьми во дворе.','summer-sasha']];
 if(run.step===6&&d[4]===0)extra=[['Перед ужином ты ещё раз открываешь фотографию с рынка. Саша замечает экран, но не заглядывает через плечо.'],['Я поставила её в избранное. Обычно я свои фотографии удаляю.','summer-heroine'],['Тогда пусть побудет. Ей там хорошо.','summer-sasha']];
 if(run.step===6&&d[4]===1)extra=[['На балконе Саша показывает снимок продавщицы с лишним лимоном.'],['Выбрал твой кадр. Можно подписать: «Увидела ты, кнопку нажал я»?','summer-sasha'],['Лучше без подписи. Мы и так знаем.','summer-heroine']];
 if(run.step===8&&d[6]===0)extra=[['Вчера за столом ты сказала, что хочешь увидеть своё имя на обложке. Сейчас Саша смотрит на тебя, и тебе не приходится объяснять, что украли не просто текст.']];
 if(run.step===8&&d[6]===1)extra=[['Ты ещё не рассказывала Саше о рукописи. Сейчас слова приходится подбирать заново.'],['Я написала книгу. Никому здесь не говорила. Это её название на афише.','summer-heroine'],['Он садится рядом, оставляя между вами место для сумки. Не торопит, пока ты решаешь, с чего начать.']];
 if(run.step===11&&d[4]===0)extra=[['Перед зеркалом ты открываешь портрет с рынка. Там нет платья, причёски и нужного выражения лица. И всё-таки та женщина нравится тебе. Сегодня ты одеваешься для неё.']];
 if(run.step===12&&d[11]===0)extra=[['У входа Саша опускает камеру, когда ты проходишь мимо. Твоё лицо не окажется среди фестивальных кадров — об этом вы уже договорились.']];
 if(run.step===12&&d[11]===1)extra=[['Перед входом приходит сообщение от Саши: «У боковой лестницы. Обратную дорогу помню». Ты сохраняешь его, словно билет домой.']];
 return [...extra.flatMap(([text,speaker])=>compactFrame({text,...(speaker?{speaker}: {})})),...base];}

readingFrames[1][3]=readingFrames[1][3].filter(f=>!f.text.startsWith('Саша оказывается фотографом.')&&!f.text.startsWith('Это выясняется само собой:'));
